      if (player.magnetTimer > 0) {
        const dx = player.x - p.x;
        const dy = player.y - p.y;
        const dist = Math.hypot(dx, dy);
        if (dist < 300) {
          p.x += (dx / dist) * 6;
          p.y += (dy / dist) * 6;
        }
      }

      if (p.life <= 0 || p.x < -40) {
        this.powerups.splice(i, 1);
